import {speakerEdits} from "./speaker-edits.js";
import {mediaFilters} from "./media-filters.js";
import {SourceClockMedia,sourceClockOptions} from "./source-clock.js";
import {speakerAssignments} from "./speaker-assignments.js";
import {SpeakerAnalysis,diarizationOptions} from "./diarization.js";
import {VisualSummaries,visualSummaryReferences} from "./visual-summaries.js";
import {CaptionBatches,captionTimes} from "./caption-batches.js";
import {FrameCaptions} from "./captions.js";
import type { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import * as z from "zod/v4";
import type { ServerConfig } from "../config.js";
import { errorDetails } from "../errors.js";
import { MediaLibrary, transcriptSchema } from "./media-library.js";
import { VisualSearch, visualRange, visualScope, visualRefinement } from "./visual.js";
import { SpeechAnalysis } from "./speech.js";
import {speechOptions} from "./speech-options.js";
import { AnalysisJobs, jobSchema } from "./jobs.js";
import {Collections, collectionSchema} from "./collections.js";
import {WatchFolders,watchOptions} from "./watch-folders.js";
import {ProjectSnapshots,savedMobFilters} from "./project-snapshots.js";
import {AafBuilder,aafBuildSchema,aafMergeSchema} from "./aaf-builder.js";
import {MediaSummaries} from "./summaries.js";
import {MediaQc,qcOptions} from "./qc.js";
import {QcReports} from "./qc-reports.js";
import {ShotDetection,shotOptions} from "./shots.js";
import {People,peopleEditSchema,peopleRange,peopleSearchOptions} from "./people.js";
import {TranscriptRevisions,transcriptEdits} from "./transcripts.js";

export function registerLibraryTools(server: McpServer, config: ServerConfig) {
  const speakers = new SpeakerAnalysis(config);
  const library = new MediaLibrary(config);
  const captions = new FrameCaptions(config);
  const captionBatches = new CaptionBatches(config);
  const visual = new VisualSearch(config);
  const speech = new SpeechAnalysis(config);
  const jobs = new AnalysisJobs(config);
  const collections = new Collections(config);
  const watches = new WatchFolders(config);
  const snapshots = new ProjectSnapshots(config);
  const people = new People(config);
  const qc = new MediaQc(config);
  const qcReports = new QcReports(config);
  const shots = new ShotDetection(config);
  const summaries = new MediaSummaries(config);
  const visualSummaries = new VisualSummaries(config);
  const aafBuilder = new AafBuilder(config);
  const transcripts = new TranscriptRevisions(config);
  const previousClose=server.server.onclose;
  let cleanup:Promise<void>|undefined;
  const dispose=()=>cleanup??=Promise.allSettled([jobs.closeAndWait(),watches.stopAndWait(),visual.dispose(),speech.dispose(),summaries.dispose(),captions.dispose(),captionBatches.dispose(),visualSummaries.dispose()]).then(results=>{
    const errors=results.flatMap(result=>result.status==="rejected"?[result.reason]:[]);
    if(errors.length)throw new AggregateError(errors,"MCP library cleanup failed");
  });
  server.server.onclose=()=>{void dispose().catch(()=>{});previousClose?.();};
  const close=server.close.bind(server);
  server.close=async()=>{try{await close();}finally{await dispose();}};
  const id = z.string().regex(/^[a-f0-9]{64}$/);
  const ids = z.array(id).min(1).max(100);
  const read = {readOnlyHint:true, destructiveHint:false, openWorldHint:false, idempotentHint:true};
  const write = {readOnlyHint:false, destructiveHint:false, openWorldHint:false, idempotentHint:false};
  const result = async (name: string, fn: () => Promise<unknown>) => {
    try { const data = {ok:true,tool:name,data:await fn()}; return {content:[{type:"text" as const,text:JSON.stringify(data)}],structuredContent:data}; }
    catch(error) { const data={ok:false,tool:name,error:errorDetails(error)}; return {content:[{type:"text" as const,text:JSON.stringify(data)}],structuredContent:data,isError:true}; }
  };
  server.registerTool("avid_prepare_source_clock_media",{description:"Create a new MOV from checksum-selected local MP4/MOV media: copy one H.264 video stream and normalize one stereo audio stream to source-clock 48kHz/24-bit PCM. Explicit absolute stream indexes; at most 600 seconds and 4 GiB. Verifies video metadata/essence, PCM and packet continuity, preserving the source. Requires export; no Avid import/relink or color qualification.",inputSchema:{options:sourceClockOptions},annotations:write},({options})=>result("avid_prepare_source_clock_media",()=>new SourceClockMedia(config).prepare(options)));
  server.registerTool("avid_source_clock_status",{description:"Inspect a saved source-clock preparation by its directory UUID. Validates scoped source identity, outcome records and any completed output checksum. Distinguishes unresolved, failure_recorded and receipt_matches_files. Worker state remains unknown; no retry, cleanup, fresh essence verification or Avid import.",inputSchema:{runId:z.string().uuid()},annotations:read},({runId})=>result("avid_source_clock_status",()=>new SourceClockMedia(config).status(runId)));
  server.registerTool("avid_list_source_clock_attempts",{description:"Discover saved preparation attempts for an authorized checksum-selected source after reconnecting. Bounded pages count examined records, may be empty with continuation, and omit other sources. Returns run UUIDs for avid_source_clock_status; no output verification, worker-state or completion claim.",inputSchema:{file:z.string().min(1),expectedSha256:id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(50).default(20)},annotations:read},({file,expectedSha256,after,limit})=>result("avid_list_source_clock_attempts",()=>new SourceClockMedia(config).list(file,expectedSha256,after,limit)));
  server.registerTool("avid_summarize_captions",{description:"Build a four-child visual hierarchy from checksum-selected frame captions. Leaves preserve caption text; parent text is locally generated and needs image review. Samples do not establish continuous video coverage. Use a visual_summary job for cancellation.",inputSchema:{id,references:visualSummaryReferences},annotations:write},({id,references})=>result("avid_summarize_captions",()=>visualSummaries.generate(id,references)));
  server.registerTool("avid_visual_summary_node",{description:"Read a visual summary overview or child node with original descendant captions and verified image paths. Checks caption/source/image provenance; use avid_read_caption to view the image.",inputSchema:{revision:z.string().uuid(),nodeId:z.string().optional()},annotations:read},({revision,nodeId})=>result("avid_visual_summary_node",()=>visualSummaries.node(revision,nodeId)));
  server.registerTool("avid_list_visual_summaries",{description:"List visual summaries with checksums for authorized media, including after caption deletion. Listing checks structure but does not verify caption provenance; read a node for verification. Limit bounds examined files; follow nextAfter through empty pages. Unavailable records omit content; mediaIdentityVerified=false does not associate them with the requested media.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},({id,after,limit})=>result("avid_list_visual_summaries",()=>visualSummaries.list(id,after,limit)));
  server.registerTool("avid_delete_visual_summary",{description:"Delete only a visual summary after checksum verification, preserving captions and source media. Requires project-write.",inputSchema:{revision:z.string().uuid(),expectedSha256:z.string().regex(/^[a-f0-9]{64}$/)},annotations:{...write,destructiveHint:true}},({revision,expectedSha256})=>result("avid_delete_visual_summary",()=>visualSummaries.remove(revision,expectedSha256)));
  server.registerTool("avid_correct_speaker_analysis",{description:"Create a self-contained child analysis by replacing/removing/adding source-time speaker spans or merging two existing labels. Edits run in order, require project-write and the selected checksum, and retain original model output, parent analysis and source media. New labels can split clusters; no identity is inferred.",inputSchema:{analysisId:z.string().uuid(),expectedSha256:id,edits:speakerEdits},annotations:write},({analysisId,expectedSha256,edits})=>result("avid_correct_speaker_analysis",()=>speakers.correct(analysisId,expectedSha256,edits)));
  server.registerTool("avid_transcript_speaker_assignments",{description:"Read paginated caller-selected speaker assignment provenance saved in a checksum-selected transcript revision. Does not infer identity or require models. Older ordinary transcript revisions return no assignment record.",inputSchema:{id,revision:z.string().uuid(),expectedSha256:id,offset:z.number().int().min(0).max(1000).default(0),limit:z.number().int().min(1).max(500).default(100)},annotations:read},({id,revision,expectedSha256,offset,limit})=>result("avid_transcript_speaker_assignments",()=>transcripts.speakerAssignmentPage(id,revision,expectedSha256,offset,limit)));
  server.registerTool("avid_assign_transcript_speakers",{description:"Apply explicit segment-to-speaker choices to a new transcript revision, retaining original text/timing and the parent. Requires checksum-selected inputs and project-write. Chosen labels must overlap each segment; multiple candidates or partial analysis coverage require explicit flags. Optional display names are caller supplied, never inferred.",inputSchema:{analysisId:z.string().uuid(),analysisSha256:id,transcriptRevision:z.string().uuid(),transcriptSha256:id,assignments:speakerAssignments},annotations:write},({analysisId,analysisSha256,transcriptRevision,transcriptSha256,assignments})=>result("avid_assign_transcript_speakers",()=>speakers.assign(analysisId,analysisSha256,transcriptRevision,transcriptSha256,assignments)));
  server.registerTool("avid_align_speakers",{description:"Compare a checksum-selected speaker analysis with an explicit transcript revision. Returns paginated segment overlap candidates, gaps and simultaneous-speaker ambiguity. Read-only; does not assign words or infer identities. Fractions are time coverage, not confidence.",inputSchema:{analysisId:z.string().uuid(),analysisSha256:id,transcriptRevision:z.string().uuid(),transcriptSha256:id,after:z.number().int().min(-1).max(100000).default(-1),limit:z.number().int().min(1).max(100).default(100),candidateLimit:z.number().int().min(1).max(100).default(20)},annotations:read},({analysisId,analysisSha256,transcriptRevision,transcriptSha256,after,limit,candidateLimit})=>result("avid_align_speakers",()=>speakers.align(analysisId,analysisSha256,transcriptRevision,transcriptSha256,after,limit,candidateLimit)));
  server.registerTool("avid_recover_speaker_cleanup",{description:"Restore an intact Windows speaker cleanup directory after verifying checkpoint, owner, audio and stopped processes. Refuses partial/changed contents or an existing destination. Does not restart analysis.",inputSchema:{name:z.string().min(1).max(100),expectedCheckpointSha256:id},annotations:write},({name,expectedCheckpointSha256})=>result("avid_recover_speaker_cleanup",()=>speakers.recoverCleanup(name,expectedCheckpointSha256)));
  server.registerTool("avid_cleanup_speaker_run",{description:"Remove a checksum-selected incomplete speaker run on Windows only after verifying its bound owner is absent, no observed process references its directory, and only expected files exist. Published, changed, active and legacy ownerless runs are refused.",inputSchema:{analysisId:z.string().uuid(),expectedCheckpointSha256:id},annotations:{...write,destructiveHint:true}},({analysisId,expectedCheckpointSha256})=>result("avid_cleanup_speaker_run",()=>speakers.cleanup(analysisId,expectedCheckpointSha256)));
  server.registerTool("avid_speaker_checkpoint",{description:"Verify a saved speaker audio checkpoint and return its checksum. Presence does not establish worker termination; old runs may have no checkpoint.",inputSchema:{analysisId:z.string().uuid()},annotations:read},({analysisId})=>result("avid_speaker_checkpoint",()=>speakers.checkpoint(analysisId)));
  server.registerTool("avid_resume_speakers",{description:"Copy checksum-selected speaker audio into a new analysis and rerun inference, retaining the parent. Refuses published parents and changed source/audio/runtime. Does not resume inside model inference.",inputSchema:{analysisId:z.string().uuid(),expectedSha256:id},annotations:write},({analysisId,expectedSha256})=>result("avid_resume_speakers",()=>speakers.resume(analysisId,expectedSha256)));
  server.registerTool("avid_diarize_audio",{description:"Analyze up to 600 seconds using installed local diarization models. Save checksum-bound anonymous speaker spans in source time. Labels may split or combine voices; review required. Use a diarization job for cancellation; verified audio checkpoints can be reused in a new run; model inference restarts.",inputSchema:{id,start:z.number().nonnegative(),end:z.number().positive(),options:diarizationOptions.default({speakers:-1,threshold:0.5})},annotations:write},({id,start,end,options})=>result("avid_diarize_audio",()=>speakers.generate(id,start,end,options)));
  server.registerTool("avid_speaker_analysis",{description:"Read a page of saved speaker spans after source and PCM verification. Effective view includes caller corrections; machine view retains original model output. Does not identify people or assign transcript words.",inputSchema:{analysisId:z.string().uuid(),offset:z.number().int().min(0).max(5000).default(0),limit:z.number().int().min(1).max(500).default(100),view:z.enum(["effective","machine"]).default("effective")},annotations:read},({analysisId,offset,limit,view})=>result("avid_speaker_analysis",()=>speakers.read(analysisId,offset,limit,view)));
  server.registerTool("avid_speaker_analyses",{description:"Discover completed speaker analyses for indexed media. Incomplete unpublished outputs are omitted; damaged audio is reported as unavailable.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},({id,after,limit})=>result("avid_speaker_analyses",()=>speakers.list(id,after,limit)));
  server.registerTool("avid_delete_speaker_analysis",{description:"Delete only the checksum-matched speaker record and extracted PCM. Refuses unexpected files and preserves source media.",inputSchema:{analysisId:z.string().uuid(),expectedSha256:id},annotations:{...write,destructiveHint:true}},({analysisId,expectedSha256})=>result("avid_delete_speaker_analysis",()=>speakers.remove(analysisId,expectedSha256)));
  server.registerTool("avid_caption_batch",{description:"Generate reviewable captions at 1–120 increasing seek times, saving each completed caption. Use a caption_batch job for cancellation.",inputSchema:{id,times:captionTimes},annotations:write},({id,times})=>result("avid_caption_batch",()=>captionBatches.generate(id,times)));
  server.registerTool("avid_caption_runs",{description:"Discover caption batches with verified progress. A partial run does not prove that its worker stopped.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},({id,after,limit})=>result("avid_caption_runs",()=>captionBatches.list(id,after,limit)));
  server.registerTool("avid_caption_run",{description:"Verify caption batch source, checkpoints and completion. Editing or deleting referenced captions invalidates verification.",inputSchema:{runId:z.string().uuid()},annotations:read},({runId})=>result("avid_caption_run",()=>captionBatches.status(runId)));
  server.registerTool("avid_resume_captions",{description:"Create a new caption batch reusing verified saved captions. Stop the original worker first. Use a caption_resume job for cancellation.",inputSchema:{runId:z.string().uuid()},annotations:write},({runId})=>result("avid_resume_captions",()=>captionBatches.resume(runId)));
  server.registerTool("avid_caption_frame",{description:"Generate a local Florence caption for one requested video seek time with a retained source image and model provenance. Requires cached caption models, export and project-write. Text can omit or invent details; inspect the image before using it. Use a caption job for cancellable execution.",inputSchema:{id,time:z.number().nonnegative()},annotations:write},({id,time})=>result("avid_caption_frame",()=>captions.generate(id,time)));
  server.registerTool("avid_read_caption",{description:"Read a frame caption and its source-image path after checking source and image integrity. Edited text is not automatically fact-verified.",inputSchema:{captionId:z.string().uuid()},annotations:read},async({captionId})=>{let encoded:string|undefined;const response=await result("avid_read_caption",async()=>{const review=await captions.withImage(captionId);encoded=review.image;return review.data;});return encoded?{...response,content:[...response.content,{type:"image" as const,data:encoded,mimeType:"image/jpeg"}]}:response;});
  server.registerTool("avid_list_captions",{description:"Discover saved frame captions for authorized media, with pagination and per-caption unavailable results.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},({id,after,limit})=>result("avid_list_captions",()=>captions.list(id,after,limit)));
  server.registerTool("avid_correct_caption",{description:"Replace caption text using its current checksum; retains the original machine text and model provenance. Requires project-write; edited means changed, not fact-verified.",inputSchema:{captionId:z.string().uuid(),expectedSha256:z.string().regex(/^[a-f0-9]{64}$/),text:z.string().trim().min(1).max(4000)},annotations:write},({captionId,expectedSha256,text})=>result("avid_correct_caption",()=>captions.correct(captionId,expectedSha256,text)));
  server.registerTool("avid_delete_caption",{description:"Delete a saved caption and its sampled image after checksum verification. Requires project-write; source media is preserved.",inputSchema:{captionId:z.string().uuid(),expectedSha256:z.string().regex(/^[a-f0-9]{64}$/)},annotations:{...write,destructiveHint:true}},({captionId,expectedSha256})=>result("avid_delete_caption",()=>captions.remove(captionId,expectedSha256)));
  server.registerTool("avid_detect_speech_language",{description:"Suggest a language from up to 30 seconds using cached multilingual Whisper. Returns reviewable language-token scores; digital silence has no candidate. Requires export for local audio extraction. Does not transcribe or change auto behavior; music/noise/mixed languages can mislead.",inputSchema:{id,start:z.number().nonnegative(),end:z.number().positive()},annotations:write},
    ({id,start,end})=>result("avid_detect_speech_language",()=>speech.detectLanguage(id,start,end)));
  server.registerTool("avid_speech_runs",{description:"Discover persisted speech runs for a media ID. Partial does not prove worker termination; unavailable runs include an error.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},
    ({id,after,limit})=>result("avid_speech_runs",()=>speech.checkpoints.list(id,after,limit)));
  server.registerTool("avid_speech_run",{description:"Read persisted speech window progress and verify source and completed transcript integrity.",inputSchema:{runId:z.string().uuid()},annotations:read},
    ({runId})=>result("avid_speech_run",()=>speech.checkpoints.status(runId)));
  server.registerTool("avid_resume_speech",{description:"Resume a partial speech run in a new run using verified generation tokens. Repeats extraction/features and preserves the original run. Requires export, project-write and cached models. Use a speech_resume job for cancellable work.",inputSchema:{runId:z.string().uuid()},annotations:write},
    ({runId})=>result("avid_resume_speech",()=>speech.resume(runId)));
  server.registerTool("avid_summary_runs",{description:"Discover persisted summary computation runs for a media ID. Partial does not prove worker termination. Runs with invalid or missing provenance are returned as unavailable with an error.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},
    ({id,after,limit})=>result("avid_summary_runs",()=>summaries.runs(id,after,limit)));
  server.registerTool("avid_summary_run",{description:"Read persisted summary node counts and verify transcript provenance and completed output.",inputSchema:{runId:z.string().uuid()},annotations:read},
    ({runId})=>result("avid_summary_run",()=>summaries.runStatus(runId)));
  server.registerTool("avid_resume_summary",{description:"Resume a partial summary in a new run after verifying transcript checksum, pinned model and node input/structure. Reuses completed nodes. Requires project-write and cached summary models; use a summary_resume job for cancellable execution.",inputSchema:{runId:z.string().uuid()},annotations:write},
    ({runId})=>result("avid_resume_summary",()=>summaries.resume(runId)));
  server.registerTool("avid_visual_index_runs",{description:"Discover persisted visual indexing runs and completed sample counts. Partial does not prove the original worker stopped. Checkpoints survive cancellation or server restart.",inputSchema:{after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(50)},annotations:read},
    ({after,limit})=>result("avid_visual_index_runs",()=>visual.checkpoints.list(after,limit)));
  server.registerTool("avid_visual_index_run",{description:"Read a visual indexing run's persisted progress without loading a model.",inputSchema:{runId:z.string().uuid()},annotations:read},
    ({runId})=>result("avid_visual_index_run",()=>visual.checkpoints.status(runId)));
  server.registerTool("avid_resume_visual_index",{description:"Resume a partial visual index in a new run, reusing its verified contiguous sample prefix. Checks model revision, source hashes and cached image hashes; computes missing samples. Requires export and cached models. Original run is preserved. Use a visual_resume job for cancellable execution.",inputSchema:{runId:z.string().uuid()},annotations:write},
    ({runId})=>result("avid_resume_visual_index",()=>visual.resume(runId)));
  server.registerTool("avid_inspect_aaf_template", {description:"Inspect a master-only Avid-exported AAF and validate/hash local media locators. Requires export for a request manifest. Does not import into Avid.",inputSchema:{template:z.string().min(1)},annotations:write},
    ({template})=>result("avid_inspect_aaf_template",()=>aafBuilder.inspect(template)));
  server.registerTool("avid_merge_aaf_references", {description:"Merge 2-16 checksum-selected local reference AAFs into a new verified template, remapping conflicting identities. Requires export and allowed local media; no native import or relink.",inputSchema:{request:aafMergeSchema},annotations:write},
    ({request})=>result("avid_merge_aaf_references",()=>aafBuilder.merge(request)));
  server.registerTool("avid_build_aaf_selects", {description:"Build a new straight-cut AAF composition preserving exported source descriptors. Requires export, current template checksum and explicit master/slot mappings. Verifies output ranges; host import/playback is separate.",inputSchema:{request:aafBuildSchema},annotations:write},
    ({request})=>result("avid_build_aaf_selects",()=>aafBuilder.build(request)));
  server.registerTool("avid_inspect_aaf_selects", {description:"Inspect one same-rate straight-cut AAF composition, expose track/source ranges and hash permitted local media. Rejects unsupported graph/rate/range structures. Requires export for a request manifest; does not import into Avid.",inputSchema:{file:z.string().min(1)},annotations:write},
    ({file})=>result("avid_inspect_aaf_selects",()=>aafBuilder.inspectSelects(file)));
  server.registerTool("avid_generate_summary", {description:"Generate a local English transcript summary hierarchy with pinned DistilBART. Requires project-write and explicitly downloaded models. Source references are checked; factual accuracy requires review. Use a summary job for longer transcripts.",inputSchema:{id,transcriptRevision:z.string().uuid()},annotations:write},
    ({id,transcriptRevision})=>result("avid_generate_summary",()=>summaries.generate(id,transcriptRevision)));
  server.registerTool("avid_summary_node", {description:"Read a generated summary overview or drill into a node, with children and deduplicated original transcript excerpts from all descendant leaves. Source coverage does not verify generated claims. Refuses changed/missing transcript provenance.",inputSchema:{revision:z.string().uuid(),nodeId:z.string().optional()},annotations:read},
    ({revision,nodeId})=>result("avid_summary_node",()=>summaries.node(revision,nodeId)));
  server.registerTool("avid_list_summaries", {description:"Discover generated summary hierarchies for indexed media. Limit bounds examined revision files; follow nextAfter even when summaries is empty. Unavailable records are reported without their content; mediaIdentityVerified=false does not associate that record with the requested media. Does not load models or repair files.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},
    ({id,after,limit})=>result("avid_list_summaries",()=>summaries.list(id,after,limit)));
  server.registerTool("avid_delete_summary", {description:"Delete a selected generated summary document with checksum validation. Transcript and source media remain. Requires project-write.",inputSchema:{revision:z.string().uuid(),expectedSha256:id},annotations:{...write,destructiveHint:true}},
    ({revision,expectedSha256})=>result("avid_delete_summary",()=>summaries.remove(revision,expectedSha256)));
  server.registerTool("avid_media_qc", {description:"Decode up to ten minutes of selected video/audio streams (absolute metadata stream indices; omit for first of each type, null to skip) for black, freeze, silence, input loudness and timestamp-variation findings. Writes JSON/HTML reports; requires export. Findings need review and are not delivery certification or perceptual sync analysis.",inputSchema:{id,options:qcOptions},annotations:write},
    ({id,options})=>result("avid_media_qc",()=>qc.analyze(id,options)));
  server.registerTool("avid_qc_reports",{description:"Discover saved QC JSON reports for a current authorized media ID. Pages scan bounded report files and may contain no matches. Returns revisions and checksums; does not rerun QC.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(50).default(20)},annotations:read},({id,after,limit})=>result("avid_qc_reports",()=>qcReports.list(id,after,limit)));
  server.registerTool("avid_read_qc_report",{description:"Read a saved QC JSON report by media ID and revision, optionally requiring its SHA-256. Verifies current source and stable report bytes; stored findings are not a new decode or delivery certification.",inputSchema:{id,revision:z.string().uuid(),expectedSha256:z.string().regex(/^[a-f0-9]{64}$/).optional()},annotations:read},({id,revision,expectedSha256})=>result("avid_read_qc_report",()=>qcReports.read(id,revision,expectedSha256)));
  server.registerTool("avid_detect_shots", {description:"Decode a source range up to one hour for threshold-based visual cuts and half-open shot intervals with representative timestamps. Requires export and FFmpeg scdet. Flashes/motion may create false cuts; use a shots job for long ranges.",inputSchema:{id,options:shotOptions},annotations:write},
    ({id,options})=>result("avid_detect_shots",()=>shots.detect(id,options)));
  server.registerTool("avid_index_visual_shots", {description:"Detect cuts and index one local CLIP midpoint per detected shot, retaining source ranges in search results. Requires export, cached models and FFmpeg; rejects over 1200 shots instead of dropping coverage. Use a visual_shots job for long ranges.",inputSchema:{id,options:shotOptions},annotations:write},
    ({id,options})=>result("avid_index_visual_shots",()=>visual.indexShots(id,options)));
  server.registerTool("avid_index_media", {description:"Index up to 100 local media files by SHA-256 into the configured output directory. No media upload.", inputSchema:{files:z.array(z.string()).min(1).max(100)},annotations:write},
    ({files})=>result("avid_index_media",()=>library.index(files)));
  server.registerTool("avid_library_metadata", {description:"Read indexed technical media metadata.",inputSchema:{ids},annotations:read},
    ({ids})=>result("avid_library_metadata",()=>library.metadata(ids)));
  server.registerTool("avid_search_media", {description:"Search indexed metadata and selected transcript revisions with case-insensitive substring matching. This is not visual or semantic search.",inputSchema:{ids,query:z.string().min(1).max(500),limit:z.number().int().min(1).max(200).default(50),revisions:z.record(id,z.string().uuid()).default({})},annotations:read},
    ({ids,query,limit,revisions})=>result("avid_search_media",()=>library.search(ids,query,limit,revisions)));
  server.registerTool("avid_import_transcript", {description:"Save an immutable local transcript revision for indexed media. Requires project-write. Returns a revision ID for search/range queries.",inputSchema:{id,segments:transcriptSchema},annotations:write},
    ({id,segments})=>result("avid_import_transcript",()=>library.importTranscript(id,segments)));
  server.registerTool("avid_transcript_revisions", {description:"Discover paginated transcript revisions, checksums and correction ancestry for indexed media.",inputSchema:{id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(50)},annotations:read},
    ({id,after,limit})=>result("avid_transcript_revisions",()=>transcripts.list(id,after,limit)));
  server.registerTool("avid_correct_transcript", {description:"Create a corrected revision by replacing/removing original segment indices or adding segments. Supports text, timing and user-supplied speaker labels. Retains the original; requires project-write and its checksum.",inputSchema:{id,revision:z.string().uuid(),expectedSha256:id,edits:transcriptEdits},annotations:write},
    ({id,revision,expectedSha256,edits})=>result("avid_correct_transcript",()=>transcripts.correct(id,revision,expectedSha256,edits)));
  server.registerTool("avid_delete_transcript_revision", {description:"Delete exactly one transcript revision with checksum checking. Other revisions and exports remain. Requires project-write.",inputSchema:{id,revision:z.string().uuid(),expectedSha256:id},annotations:{...write,destructiveHint:true}},
    ({id,revision,expectedSha256})=>result("avid_delete_transcript_revision",()=>transcripts.remove(id,revision,expectedSha256)));
  server.registerTool("avid_transcript_range", {description:"Read a bounded half-open transcript range with a continuation cursor.",inputSchema:{id,start:z.number().nonnegative(),end:z.number().positive(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(200).default(50),revision:z.string().uuid().optional()},annotations:read},
    ({id,start,end,after,limit,revision})=>result("avid_transcript_range",()=>library.transcriptRange(id,start,end,after,limit,revision)));
  server.registerTool("avid_media_artifact", {description:"Create a thumbnail, trimmed MP4 or checksum-verified copy in a unique output folder. Requires export. Validates indexed source identity and never overwrites.",inputSchema:{id,kind:z.enum(["thumbnail","clip","copy"]),start:z.number().nonnegative().default(0),end:z.number().positive().optional()},annotations:write},
    ({id,kind,start,end})=>result("avid_media_artifact",()=>library.artifact(id,kind,start,end)));
  server.registerTool("avid_media_report", {description:"Write a local HTML media inventory. Requires export.",inputSchema:{ids},annotations:write},
    ({ids})=>result("avid_media_report",()=>library.report(ids)));
  server.registerTool("avid_index_visual", {description:"Compute local CLIP embeddings for uniform frame samples, optionally in a source-time range. Maximum 120 samples per file and 1200 total; does not detect every shot. Requires separately downloaded models and export authority for cached thumbnails.",inputSchema:{ids,samplesPerFile:z.number().int().min(1).max(120).default(6),range:visualRange.optional()},annotations:write},
    ({ids,samplesPerFile,range})=>result("avid_index_visual",()=>visual.index(ids,samplesPerFile,range)));
  server.registerTool("avid_search_visual", {description:"Search a local visual index by text or a reference image with optional query.text refinement (equal-weight mean similarity); returns sampled source timestamps and CLIP similarity, not identity or probability. Text beyond 77 model tokens (including special tokens) is rejected rather than truncated; use concise scene descriptions. Optional refinement.exclude (up to eight concepts) softly lowers scores with weight 0–1; it does not guarantee concept absence.",inputSchema:{indexId:z.string().uuid(),query:z.union([z.object({text:z.string().min(1).max(500)}).strict(),z.object({image:z.string().min(1),text:z.string().min(1).max(500).optional()}).strict()]),limit:z.number().int().min(1).max(100).default(20),scope:visualScope.default({}),refinement:visualRefinement.default({exclude:[],weight:0.25})},annotations:read},
    ({indexId,query,limit,scope,refinement})=>result("avid_search_visual",()=>visual.search(indexId,query,limit,scope,refinement)));
  server.registerTool("avid_visual_samples", {description:"Inspect paginated visual-index sample timestamps and thumbnails, optionally scoped by media IDs and a half-open source-time range. Embeddings are omitted.",inputSchema:{indexId:z.string().uuid(),scope:visualScope.default({}),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(100).default(50)},annotations:read},
    ({indexId,scope,after,limit})=>result("avid_visual_samples",()=>visual.samples(indexId,scope,after,limit)));
  server.registerTool("avid_search_visual_frame", {description:"Extract a source frame at a given time and find similar indexed frames; optional text combines image/text cosine scores equally. Requires export for the reference thumbnail. Optional media/time scope limits results. refinement.exclude softly lowers unwanted-concept scores; it never guarantees absence.",inputSchema:{indexId:z.string().uuid(),id,time:z.number().nonnegative(),text:z.string().min(1).max(500).optional(),limit:z.number().int().min(1).max(100).default(20),scope:visualScope.default({}),refinement:visualRefinement.default({exclude:[],weight:0.25})},annotations:write},
    ({indexId,id,time,text,limit,scope,refinement})=>result("avid_search_visual_frame",()=>visual.searchFrame(indexId,id,time,limit,scope,refinement,text)));
  server.registerTool("avid_transcribe_media", {description:"Transcribe up to ten minutes of local audio with explicitly downloaded English or multilingual Whisper weights. Multilingual auto selects a reviewable language candidate from the first 30 seconds; explicit language codes override detection. English-only weights remain the default. Requires export and project-write. Returns a reviewable transcript revision; no diarization or accuracy guarantee.",inputSchema:{id,start:z.number().nonnegative(),end:z.number().positive(),options:speechOptions.default({model:"tiny.en",language:"auto"})},annotations:write},
    ({id,start,end,options})=>result("avid_transcribe_media",()=>speech.transcribe(id,start,end,options)));
  server.registerTool("avid_start_analysis_job", {description:"Queue analysis in a bounded local worker after saving its job record. Includes source_clock preparation of checksum-selected MP4/MOV media into separate verified outputs using the same options as avid_prepare_source_clock_media. Source-clock job status includes preparationRunId for avid_source_clock_status; an attempt may not exist before dispatch or after early validation failure. Cancellation retains partial outputs and is not rollback; inspect workerExit and treeTermination, whose outcome holds classified taskkill counts. Includes audio_sync content-offset candidates for two indexed media windows with explicit absolute audio stream and zero-based channel selectors; startSeconds selects decoded samples, not container timestamps. Execution belongs to this session; persistent history survives restart but unfinished work is not automatically resumed.",inputSchema:{job:jobSchema},annotations:write},
    ({job})=>result("avid_start_analysis_job",async()=>jobs.start(job)));
  server.registerTool("avid_analysis_job_status", {description:"Read local analysis job status and completed result.",inputSchema:{jobId:z.string().uuid()},annotations:read},
    ({jobId})=>result("avid_analysis_job_status",async()=>jobs.readStatus(jobId)));
  server.registerTool("avid_analysis_job_history", {description:"Read paginated persistent job records within the same configured roots/capabilities. Pages scan files; follow nextAfter even when records is empty. Unreadable files are counted. Unfinished records from another session are unresolved, never automatically replayed; outputs may exist. Does not resume computation.",inputSchema:{after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(50)},annotations:read},
    ({after,limit})=>result("avid_analysis_job_history",()=>jobs.journal.list(after,limit)));
  server.registerTool("avid_cancel_analysis_job", {description:"Cancel a queued or running local analysis job. Partial artifacts are retained for inspection; this does not undo completed output.",inputSchema:{jobId:z.string().uuid()},annotations:write},
    ({jobId})=>result("avid_cancel_analysis_job",async()=>jobs.cancelAndReadStatus(jobId)));
  server.registerTool("avid_media_facets", {description:"Filter selected indexed media by video codec/geometry/nominal frame rate/pixel format/color declarations, audio codec/channels/sample rate and inclusive duration bounds. Video constraints must match one video stream; audio constraints one audio stream. Returns matchingIds for visual scope plus observed facets. Uses cached probe metadata, not current content verification, HDR mastering validation or CFR certification.",inputSchema:{ids,filters:mediaFilters.default({})},annotations:read},
    ({ids,filters})=>result("avid_media_facets",()=>library.facets(ids,filters)));
  server.registerTool("avid_export_transcript", {description:"Export a selected transcript revision as TXT, JSON, CSV, SRT or VTT. Requires export.",inputSchema:{id,revision:z.string().uuid(),format:z.enum(["txt","json","csv","srt","vtt"])},annotations:write},
    ({id,revision,format})=>result("avid_export_transcript",()=>library.exportTranscript(id,revision,format)));
  server.registerTool("avid_transcript_outline", {description:"Build a bounded extractive transcript outline with source-range references. This does not generate a narrative summary.",inputSchema:{id,revision:z.string().uuid(),windowSeconds:z.number().min(10).max(3600).default(60)},annotations:read},
    ({id,revision,windowSeconds})=>result("avid_transcript_outline",()=>library.outline(id,revision,windowSeconds)));
  server.registerTool("avid_contact_sheet", {description:"Create a local HTML contact sheet with midpoint thumbnails for up to forty files. Requires export.",inputSchema:{ids:z.array(id).min(1).max(40)},annotations:write},
    ({ids})=>result("avid_contact_sheet",()=>library.contactSheet(ids)));
  server.registerTool("avid_thumbnail_strip", {description:"Create a portable HTML strip and checksum manifest with 1–120 uniform samples across a source-time range. Requires export. Labels are requested seek times, not exact decoded PTS; sampling may miss shots.",inputSchema:{id,start:z.number().nonnegative(),end:z.number().positive(),samples:z.number().int().min(1).max(120).default(12)},annotations:write},
    ({id,start,end,samples})=>result("avid_thumbnail_strip",()=>library.thumbnailStrip(id,start,end,samples)));
  server.registerTool("avid_save_collection", {description:"Save immutable curated source ranges, labels, notes and tags. Requires project-write. No editor mutation.",inputSchema:{collection:collectionSchema},annotations:write},
    ({collection})=>result("avid_save_collection",()=>collections.save(collection)));
  server.registerTool("avid_read_collection", {description:"Read a saved selects collection after validating current media scope.",inputSchema:{revision:z.string().uuid()},annotations:read},
    ({revision})=>result("avid_read_collection",()=>collections.read(revision)));
  server.registerTool("avid_list_collections", {description:"Rediscover saved local selects collections after reconnecting. Pages scan revision UUIDs; inaccessible or invalid records count as omitted without revealing contents. An empty page may have a continuation cursor. Source bytes are verified on export.",inputSchema:{after:z.string().uuid().optional(),limit:z.number().int().min(1).max(200).default(50)},annotations:read},
    ({after,limit})=>result("avid_list_collections",()=>collections.list(after,limit)));
  server.registerTool("avid_collection_range", {description:"Query a local selects stringout by timeline range, returning overlap source ranges. This does not read the live editor timeline.",inputSchema:{revision:z.string().uuid(),start:z.number().nonnegative(),end:z.number().positive(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(200).default(50)},annotations:read},
    ({revision,start,end,after,limit})=>result("avid_collection_range",()=>collections.range(revision,start,end,after,limit)));
  server.registerTool("avid_export_collection_otio", {description:"Export frame-quantized single-video-track OTIO selects with local media references. Requires export. Avid import is not verified; audio routing/effects are not authored.",inputSchema:{revision:z.string().uuid(),rate:z.number().positive().max(240)},annotations:write},
    ({revision,rate})=>result("avid_export_collection_otio",()=>collections.exportOtio(revision,rate)));
  server.registerTool("avid_configure_watch_folder", {description:"Create or replace a persistent bounded local watch folder. Requires project-write. Two stable observations precede indexing; service starts separately.",inputSchema:{options:watchOptions,watchId:z.string().uuid().optional()},annotations:write},
    ({options,watchId})=>result("avid_configure_watch_folder",()=>watches.configure(options,watchId)));
  server.registerTool("avid_list_watch_folders", {description:"List configured watch folders within current path scope and their checkpoints.",inputSchema:{},annotations:read},
    ()=>result("avid_list_watch_folders",()=>watches.list()));
  server.registerTool("avid_watch_lock_status", {description:"Inspect a scoped watch lock and local owner liveness. Running, uncertain, foreign and legacy owners cannot be recovered automatically.",inputSchema:{watchId:z.string().uuid()},annotations:read},
    ({watchId})=>result("avid_watch_lock_status",()=>watches.lockStatus(watchId)));
  server.registerTool("avid_recover_watch_lock", {description:"Explicitly release the exact inspected watch lock only when its qualified local owner PID is absent. Archives evidence; preserves checkpoints and media; does not retry scanning. Requires inspect and project-write.",inputSchema:{watchId:z.string().uuid(),expectedSha256:z.string().regex(/^[a-f0-9]{64}$/)},annotations:write},
    ({watchId,expectedSha256})=>result("avid_recover_watch_lock",()=>watches.recoverLock(watchId,expectedSha256)));
  server.registerTool("avid_remove_watch_folder", {description:"Remove a watch configuration; source media and cached analysis remain. Requires project-write.",inputSchema:{watchId:z.string().uuid()},annotations:write},
    ({watchId})=>result("avid_remove_watch_folder",()=>watches.remove(watchId)));
  server.registerTool("avid_scan_watch_folder", {description:"Run one bounded watch-folder observation/indexing pass with per-file checkpoints. Does not upload or edit source media.",inputSchema:{watchId:z.string().uuid()},annotations:write},
    ({watchId})=>result("avid_scan_watch_folder",()=>watches.scan(watchId)));
  server.registerTool("avid_watch_service", {description:"Start/stop local polling or read its status. Service belongs to this MCP session, stops at disconnect, and does not restart automatically. Stop lets the current file finish.",inputSchema:{action:z.enum(["start","stop","status"]),intervalSeconds:z.number().int().min(10).max(3600).default(30)},annotations:write},
    ({action,intervalSeconds})=>result("avid_watch_service",async()=>action==="start"?watches.start(intervalSeconds):action==="stop"?watches.stop():watches.status()));
  server.registerTool("avid_snapshot_saved_bins", {description:"Capture bounded semantic mob/track/source indexes from saved AVB files. Requires Python/pyavb. Excludes unsaved editor changes and reports unsupported effects/rates.",inputSchema:{bins:z.array(z.string()).min(1).max(100)},annotations:write},
    ({bins})=>result("avid_snapshot_saved_bins",()=>snapshots.create(bins)));
  server.registerTool("avid_saved_snapshots",{description:"Discover historical snapshot revisions allowed by current roots. Pages scan files; follow nextAfter even for empty pages. Does not check whether bins still match their captured hashes.",inputSchema:{after:z.string().uuid().optional(),limit:z.number().int().min(1).max(50).default(20)},annotations:read},
    ({after,limit})=>result("avid_saved_snapshots",()=>snapshots.list(after,limit)));
  server.registerTool("avid_verify_snapshot_bin",{description:"Explicitly compare one authorized saved bin with its snapshot SHA-256, streaming at most 512 MiB. Reports matches, changed or missing; refuses detectable concurrent writes. Does not inspect unsaved editor state, acquire locks, authorize edits or verify media.",inputSchema:{revision:z.string().uuid(),bin:z.string().min(1)},annotations:read},({revision,bin})=>result("avid_verify_snapshot_bin",()=>snapshots.verifyBin(revision,bin)));
  server.registerTool("avid_saved_snapshot_mobs",{description:"Find paginated mob identities in an authorized historical snapshot. Optional filters search name/comments by case-insensitive substring and match mobType, usageCode and numeric rate exactly. Keep filters unchanged while paging. No semantic search or current-bin freshness claim. Use returned mobId and bin path for range/complexity queries; repeated IDs remain distinct.",inputSchema:{revision:z.string().uuid(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(100).default(100),filters:savedMobFilters.optional()},annotations:read},
    ({revision,after,limit,filters})=>result("avid_saved_snapshot_mobs",()=>snapshots.mobs(revision,after,limit,filters)));
  server.registerTool("avid_saved_locator_availability",{description:"Explicitly check at most 50 saved locator declarations per page for file metadata under configured roots. Optional Windows letter//path interpretation preserves the raw declaration. Reports missing, inaccessible, unsupported and unrecorded paths separately; refuses locator symlinks and does not search, hash, open media content or relink. File presence is not Avid online or playback verification.",inputSchema:{revision:z.string().uuid(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(50).default(50),interpretAvidDrivePaths:z.boolean().default(false)},annotations:read},
    ({revision,after,limit,interpretAvidDrivePaths})=>result("avid_saved_locator_availability",()=>snapshots.locatorAvailability(revision,after,limit,interpretAvidDrivePaths)));
  server.registerTool("avid_diff_saved_snapshots", {description:"Compare paginated semantic mob/track/source changes between saved-bin snapshots. Follow nextAfter using the same baseline/candidate pair. Excludes volatile save metadata.",inputSchema:{baseline:z.string().uuid(),candidate:z.string().uuid(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(200).default(200)},annotations:read},
    ({baseline,candidate,after,limit})=>result("avid_diff_saved_snapshots",()=>snapshots.diff(baseline,candidate,after,limit)));
  server.registerTool('avid_saved_markers',{description:'Page reachable saved marker occurrences from a captured AVB snapshot. Includes text, color declarations, component paths and direct, declared-effect-input or unresolved locations. Legacy snapshots report not_recorded. Keep revision, mobId and optional disambiguating bin unchanged while paging. Does not read unsaved markers or prove effect output mapping.',inputSchema:{revision:z.string().uuid(),mobId:z.string().min(1),bin:z.string().min(1).optional(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(200).default(100)},annotations:read},
    ({revision,mobId,bin,after,limit})=>result('avid_saved_markers',()=>snapshots.markers(revision,mobId,after,limit,bin)));
  server.registerTool("avid_saved_timeline_range", {description:"Read a half-open edit-unit range and source overlaps from a saved-bin snapshot, with track ordinal and continuation. Optional absolute bin path disambiguates repeated MOB IDs; keep it unchanged while paging. Does not read unsaved/live editor state.",inputSchema:{revision:z.string().uuid(),mobId:z.string().min(1),start:z.number().int().nonnegative(),end:z.number().int().positive(),bin:z.string().min(1).optional(),trackOrdinal:z.number().int().nonnegative().optional(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(200).default(100)},annotations:read},
    ({revision,mobId,start,end,trackOrdinal,after,limit,bin})=>result("avid_saved_timeline_range",()=>snapshots.range(revision,mobId,start,end,trackOrdinal,after,limit,bin)));
  server.registerTool("avid_trace_saved_sources",{description:"Trace bounded equal-rate direct sources and recognized equal-length color-adapter input references through captured bins. Effect input traversal remains incomplete and does not verify rendered output correspondence. Stops at unsupported, unresolved, ambiguous, cyclic or mixed-rate structures. Does not establish playback or media availability.",inputSchema:{revision:z.string().uuid(),mobId:z.string().min(1),start:z.number().int().nonnegative(),end:z.number().int().positive(),bin:z.string().min(1).optional(),maxDepth:z.number().int().min(1).max(16).default(8)},annotations:read},
    ({revision,mobId,start,end,bin,maxDepth})=>result("avid_trace_saved_sources",()=>snapshots.traceSources(revision,mobId,start,end,bin,maxDepth)));
  server.registerTool("avid_verify_saved_trim",{description:"Verify an exact one-frame dual-roller change between two selected captured bins. Compares every normalized mob record and refuses unrelated edits or unsupported cuts. Does not execute editing commands or verify current unsaved state, media handles or playback.",inputSchema:{baseline:z.string().uuid(),candidate:z.string().uuid(),baselineBin:z.string().min(1),candidateBin:z.string().min(1),mobId:z.string().min(1),cut:z.number().int().nonnegative(),delta:z.union([z.literal(-1),z.literal(1)]),trackOrdinals:z.array(z.number().int().nonnegative()).min(1).max(128)},annotations:read},
    ({baseline,candidate,baselineBin,candidateBin,mobId,cut,delta,trackOrdinals})=>result("avid_verify_saved_trim",()=>snapshots.verifyTrim(baseline,candidate,baselineBin,candidateBin,mobId,cut,delta,trackOrdinals)));
  server.registerTool("avid_saved_source_resolution", {description:"Page every direct source ID in a saved snapshot with resolved/unresolved/ambiguous status across captured bins. Follow nextAfter with the same revision. This does not establish media availability.",inputSchema:{revision:z.string().uuid(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(200).default(100)},annotations:read},
    ({revision,after,limit})=>result("avid_saved_source_resolution",()=>snapshots.sourceResolution(revision,after,limit)));
  server.registerTool("avid_saved_source_usage", {description:"Find paginated direct source-mob uses across snapshot bins and tracks. Optionally include declared color-adapter inputs without claiming rendered correspondence. Follow nextAfter using the same revision/source ID and includeEffectInputs option. Opaque effects/retimes are explicitly incomplete.",inputSchema:{revision:z.string().uuid(),sourceMobId:z.string().min(1),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(500).default(500),includeEffectInputs:z.boolean().default(false)},annotations:read},
    ({revision,sourceMobId,after,limit,includeEffectInputs})=>result("avid_saved_source_usage",()=>snapshots.usage(revision,sourceMobId,after,limit,includeEffectInputs)));
  server.registerTool("avid_saved_sequence_complexity",{description:"Report saved snapshot track/node/source counts, opaque structure and bounded counts by saved direct effect ID. Optional absolute bin path disambiguates repeated MOB IDs. Not a recursive effect inventory, render estimate or live timeline.",inputSchema:{revision:z.string().uuid(),mobId:z.string().min(1),bin:z.string().min(1).optional()},annotations:read},
    ({revision,mobId,bin})=>result("avid_saved_sequence_complexity",()=>snapshots.complexity(revision,mobId,bin)));
  server.registerTool("avid_people_runs",{description:"Discover persisted people computation runs for authorized media, including partial extraction/analysis. Partial does not prove a worker stopped; unavailable runs include an error.",inputSchema:{mediaId:id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},
    ({mediaId,after,limit})=>result("avid_people_runs",()=>people.runs.list(mediaId,after,limit)));
  server.registerTool("avid_people_run",{description:"Verify people run source/frame/crop/checkpoint integrity and original completed index checksum, and report persisted progress. Later index edits invalidate the original completion checksum.",inputSchema:{indexId:z.string().uuid()},annotations:read},
    ({indexId})=>result("avid_people_run",()=>people.runs.status(indexId)));
  server.registerTool("avid_resume_people",{description:"Resume a partial people run in a new index using verified extracted frames and face-analysis checkpoints. Preserves the original run; requires export, project-write and cached face models. Use a people_resume job for cancellable work.",inputSchema:{indexId:z.string().uuid()},annotations:write},
    ({indexId})=>result("avid_resume_people",()=>people.resume(indexId)));
  server.registerTool("avid_people_indices",{description:"Discover saved people indices containing an authorized media ID, including zero-face sources with saved coverage. Paginates by index ID; invalid accessible indices are reported as unavailable. Partial or deleted indices without a final index are omitted.",inputSchema:{mediaId:id,after:z.string().uuid().optional(),limit:z.number().int().min(1).max(100).default(20)},annotations:read},
    ({mediaId,after,limit})=>result("avid_people_indices",()=>people.discover(mediaId,after,limit)));
  server.registerTool("avid_find_similar_faces",{description:"Rank saved face appearances by cosine similarity to a selected reference face, across up to 20 authorized indices. Optional media/time filters and score threshold; at most 100 matches. Excludes the selected occurrence. Uses cached features without model inference. Similarity is not identity verification.",inputSchema:{referenceIndexId:z.string().uuid(),referenceFaceId:z.string().regex(/^f\d{5}$/),options:peopleSearchOptions.default({threshold:0.45,limit:50})},annotations:read},
    ({referenceIndexId,referenceFaceId,options})=>result("avid_find_similar_faces",()=>people.similar(referenceIndexId,referenceFaceId,options)));
  server.registerTool("avid_index_people", {description:"Detect and group similar faces using cached YuNet/SFace models, with up to 120 samples per file and 1200 total. Optional range applies to every source. Returns sampled coverage; brief appearances may be missed. Requires export and project-write. Names are never inferred. For long work use a people analysis job.",inputSchema:{ids:z.array(id).min(1).max(20),samples:z.number().int().min(1).max(120).default(12),threshold:z.number().min(0).max(1).default(0.45),range:peopleRange.optional()},annotations:write},
    ({ids,samples,threshold,range})=>result("avid_index_people",()=>people.index(ids,samples,threshold,range)));
  server.registerTool("avid_people_clusters", {description:"Read paginated similarity groups and user-supplied names. These are not verified identities.",inputSchema:{indexId:z.string().uuid(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(100).default(50)},annotations:read},
    ({indexId,after,limit})=>result("avid_people_clusters",()=>people.list(indexId,after,limit)));
  server.registerTool("avid_people_faces", {description:"Read bounded source timestamps, face boxes and local crop paths, optionally by cluster. Embeddings are not returned.",inputSchema:{indexId:z.string().uuid(),clusterId:z.string().uuid().optional(),after:z.number().int().min(-1).default(-1),limit:z.number().int().min(1).max(100).default(50)},annotations:read},
    ({indexId,clusterId,after,limit})=>result("avid_people_faces",()=>people.faces(indexId,clusterId,after,limit)));
  server.registerTool("avid_edit_people", {description:"Name, merge, move, remove a face, or recluster a reviewed people index with revision checking. Reclustering resets names. Face removal deletes its crop/embedding; sampled frames remain until whole-index deletion.",inputSchema:{indexId:z.string().uuid(),expectedRevision:z.string().uuid(),operation:peopleEditSchema},annotations:{...write,destructiveHint:true}},
    ({indexId,expectedRevision,operation})=>result("avid_edit_people",()=>people.edit(indexId,expectedRevision,operation)));
  server.registerTool("avid_delete_people_index", {description:"Delete this index's face embeddings, crops and sampled frames after revision validation. Source media and other analysis indexes remain.",inputSchema:{indexId:z.string().uuid(),expectedRevision:z.string().uuid()},annotations:{...write,destructiveHint:true}},
    ({indexId,expectedRevision})=>result("avid_delete_people_index",()=>people.remove(indexId,expectedRevision)));
}
